    remaining = bins - item
    valid = remaining >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    min_rem = np.min(remaining[valid])
    relative_penalty = -((remaining - min_rem) / (min_rem + 1e-8))
    return np.where(valid, relative_penalty, -np.inf)
```

